#[derive(Deserialize)]
struct ItemPayload {
    #[serde(deserialize_with = "validate_name")]
    name: String,
    quantity: i32,
}

pub struct InventoryItem { name: String, quantity: i32 } // fields private: no post-hoc bypass

impl InventoryItem {
    pub fn new(payload: ItemPayload) -> Result<Self, Error> {
        if payload.quantity < 0 { return Err(Error::NegativeQuantity); }
        Ok(InventoryItem { name: payload.name, quantity: payload.quantity })
    }
}
